package io.github.toolazytoname.xiaohei;
public final class RootProfileTransactionTest {public static void main(String[] x){String a="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",b="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";RootProfileTransaction t=new RootProfileTransaction();ok(t.precheck("xiaohei-device-profile-v1",a));ok(t.snapshot(a));ok(t.markApplied());deny(t.rollback(b));ok(t.rollback(a));ok(t.verifyAfterReboot(a));if(t.state()!=RootProfileTransaction.State.REBOOT_VERIFIED)throw new AssertionError();RootProfileTransaction bad=new RootProfileTransaction();deny(bad.precheck("other",a));deny(bad.snapshot(a));System.out.println("PASS RootProfileTransactionTest transitions=5 mismatch=1 invalid_state=2 installer_calls=0 reboot_device_calls=0");}private static void ok(RootProfileTransaction.Decision d){if(d!=RootProfileTransaction.Decision.ALLOW)throw new AssertionError();}private static void deny(RootProfileTransaction.Decision d){if(d==RootProfileTransaction.Decision.ALLOW)throw new AssertionError();}}
